import{_ as t,c as _,j as e,a as l,o as n}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"既然可以设置止损，为什么还有那么多人爆仓？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/止损/既然可以设置止损，合约为什么还有那么多人爆仓.md","filePath":"stock/止损/既然可以设置止损，合约为什么还有那么多人爆仓.md"}'),r={name:"stock/止损/既然可以设置止损，合约为什么还有那么多人爆仓.md"};function o(s,a,c,p,d,i){return n(),_("div",null,a[0]||(a[0]=[e("h1",{id:"既然可以设置止损-为什么还有那么多人爆仓",tabindex:"-1"},[l("既然可以设置止损，为什么还有那么多人爆仓？ "),e("a",{class:"header-anchor",href:"#既然可以设置止损-为什么还有那么多人爆仓","aria-label":'Permalink to "既然可以设置止损，为什么还有那么多人爆仓？"'},"​")],-1),e("p",null,"因为人不能完全理性的处理超额预期损失之外的决策失误，预期外的亏损越大，越无法理性处理。",-1),e("p",null,"简单来讲就是，在小幅亏损下，人有限的理性可以简单的处理这种决策失误，并及时对错误决策进行简单修正。但是在承受非预期内的大幅亏损下，人是做不到止损的，因为此时掌控个人决策的不再是理性，而是情绪。",-1),e("p",null,"我们可以这么认为：作为一个人，你的人性决定了你的理性是有限的，因为你的理性是有限的，所以你无法在超越你的理性可掌控的范围内做出任何理性的决策。而这，就是很多交易者明明知道会爆仓，但是却只能眼睁睁看着爆仓却迟迟无法做出止损决策的原因，因为他的情绪系统还在对亏损的事实进行抗拒和辩解，这个人无法在短时间去接受他需要面临巨大损失的事实。",-1),e("p",null,"这种反应不止是反应在交易上，也反应在生活的方方面面。",-1),e("p",null,"只要是在你的理性承受范围外的损失，无论是金钱还是情感亦或者是其他，你都会陷入震惊--->痛苦---->抗拒现实---->用力挽救---->挽救无效----->陷入绝望----->心灰意冷----->逐渐接纳----->恢复振作，这么一套心理流程，整个心理过程基本是不会有变化的，因为这属于人的心理调整节律规则。",-1),e("p",null,"一旦个人丧失理性陷入到这个流程中去，那么就只能走完这套流程才能恢复理性，从理性到非理性再从非理性回归理性，个人必须要经历从抗拒到绝望，从绝望到接纳的过程，而人只会在绝望时止损，抗拒中是不会止损的，所以你对亏损的抗拒时间长短就决定了你的止损能力的高低。",-1),e("p",null,"那么这也就回到了开头说的，人只有在预期内的亏损是能够迅速止损的，因为有预期，所以不抗拒，理性则得以保留。而一旦陷入非预期中的亏损，你的抗拒心理时间就会延长，如果这个非预期亏损特别巨大，那么你就完全不可能止损，而是会拼尽全力去挽救，最终输到侵家荡产为止。",-1)]))}const f=t(r,[["render",o]]);export{m as __pageData,f as default};
